import{_ as a}from"./chunks/landing_page_1.aE_D7HLi.js";import{_ as t,a as s,b as r}from"./chunks/landing_page_4.DDy68RQt.js";import{_ as o,o as i,c as n,a2 as l}from"./chunks/framework.Ce1WstT_.js";const b=JSON.parse('{"title":"1. Project Overview","description":"","frontmatter":{},"headers":[],"relativePath":"overview/introduction.md","filePath":"overview/introduction.md"}'),c={name:"overview/introduction.md"};function d(u,e,m,h,p,g){return i(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="_1-project-overview" tabindex="-1">1. Project Overview <a class="header-anchor" href="#_1-project-overview" aria-label="Permalink to &quot;1. Project Overview&quot;">​</a></h1><p>The <strong>Mini ERP + CRM Operations Portal</strong> is a software platform designed specifically for small-to-medium wholesale and distribution businesses.</p><h2 id="the-business-problem" tabindex="-1">The Business Problem <a class="header-anchor" href="#the-business-problem" aria-label="Permalink to &quot;The Business Problem&quot;">​</a></h2><p>The platform bridges essential operational functions across sales teams, warehouse personnel, accounts departments, and executive administration. It acts as a single source of truth for operations that are typically fragmented across spreadsheets or legacy software.</p><h2 id="target-audience" tabindex="-1">Target Audience <a class="header-anchor" href="#target-audience" aria-label="Permalink to &quot;Target Audience&quot;">​</a></h2><ul><li>Wholesale distributors</li><li>Small-to-medium inventory-centric businesses</li><li>Operations teams (Sales agents, Warehouse managers, Account executives)</li></ul><h2 id="core-business-workflow" tabindex="-1">Core Business Workflow <a class="header-anchor" href="#core-business-workflow" aria-label="Permalink to &quot;Core Business Workflow&quot;">​</a></h2><p>The platform is designed around the following unified workflow:</p><ol><li><strong>Customer (Lead)</strong>: A sales agent adds a new prospective customer to the system.</li><li><strong>CRM</strong>: The sales team logs interactions (Follow-ups) and transitions the customer to ACTIVE.</li><li><strong>Product</strong>: Warehouse or Admin adds product catalogs, determining SKU, pricing, and initial stock via Stock Movements.</li><li><strong>Inventory</strong>: The system tracks all inventory balances, preventing stockouts and negative quantities.</li><li><strong>Sales Challan</strong>: Sales generates a draft order (Challan) for the customer&#39;s products.</li><li><strong>Dashboard / Operational Tracking</strong>: Executives and operators monitor active leads, stock levels, and daily sales dispatches via a centralized dashboard.</li></ol><h2 id="visual-reference" tabindex="-1">Visual Reference <a class="header-anchor" href="#visual-reference" aria-label="Permalink to &quot;Visual Reference&quot;">​</a></h2><p><img src="'+a+'" alt="Landing Page 1"><img src="'+t+'" alt="Landing Page 2"><img src="'+s+'" alt="Landing Page 3"><img src="'+r+'" alt="Landing Page 4"></p>',11)])])}const w=o(c,[["render",d]]);export{b as __pageData,w as default};
